#pragma once

// Message metadata: passed to the subscriber callback with every delivery. Meta is generated by the
// broker at publish time; its content is identical on the C++ and SV sides (it crosses via DPI).

#include <cstdint>
#include <string>
#include <string_view>

namespace shuttle {

// `topic_name` / `type_tag` are views into storage the broker owns for the
// whole process (the topic-table key and the type binding's tag), so a Meta --
// or a MailboxItem holding one -- may outlive the frame it arrived with. The
// broker never hands out a view of a caller's temporary; user code treats them
// as ordinary strings (`meta.topic_name == "dev.tx"`,
// `std::string s{meta.topic_name};`, `s = meta.topic_name;`). They are not
// guaranteed NUL-terminated: anything that needs a `const char*` (the DPI
// export table) materializes a std::string first.
struct Meta {
  std::string_view topic_name;  // the concrete topic the frame was published to (never a wildcard
                                // pattern: a wildcard subscription is told the real name here)
  std::string_view type_tag;    // message type tag (SHUTTLE_REFLECT name / typeid name)
  std::uint64_t topic_seq;  // index of this frame within its topic: a per-topic counter starting at
                            // 1, assigned by the broker, identical across languages. (topic_name,
                            // topic_seq) identifies a frame -- neither field does on its own
  std::int64_t time_fs;     // simulation time at publish (femtoseconds), from now_fs()
  std::uint32_t corr_id = 0;  // correlation id of this frame, assigned by the *publisher* (the
                              // broker neither interprets nor validates it); 0 = not part of a
                              // correlated exchange. It rides in the frame header, so the payload
                              // type needs no extra field and any encodable type works, third-party
                              // ones included. `Requester` allocates it, `serve` echoes it
};

// `corr_id` is the AMQP `correlation_id` idea, scoped to one simulation process (see
// requester.hpp for the allocation rule).

// Current simulation time (femtoseconds).
// svdpi backend: provided over DPI by the SV-side shuttle_sv_time_fs() (converted from $realtime);
// systemc backend: converted from sc_time_stamp().
std::int64_t now_fs();

}  // namespace shuttle
